28:       { word: 'LÓGICA', hint: 'Dale vuelta a una idea con un remate inesperado.', rhymes: ['simbólica', 'metáfora', 'histórica', 'caótica'] },
29:       { word: 'BRÚJULA', hint: 'Perdete un segundo y encontrá tu propio norte.', rhymes: ['burbuja', 'aguja', 'dibujan', 'empujan'] },
