34:       { word: 'LA VEREDA', hint: 'Meté dos sílabas por pulso y pintá la escena.', rhymes: ['moneda', 'rueda', 'queda', 'vereda'] },
35:       { word: 'UN MATE', hint: 'Doble tempo: mantené el aire y cambiá el remate.', rhymes: ['debate', 'late', 'rescate', 'combate'] },
36:       { word: 'LA PLAZA', hint: 'Hacé que responda el barrio, sin perder el pulso.', rhymes: ['amenaza', 'abraza', 'terraza', 'calabaza'] },
