252:   function renderEmptyPrompt() {
253:     ui.round.textContent = 'RONDA 01';
254:     ui.promptLabel.textContent = 'TU CONCEPTO';
255:     ui.promptIndex.textContent = '#01';
256:     ui.promptWord.textContent = 'LISTA';
257:     ui.promptHint.textContent = 'Marcá cuatro pulsos para empezar';
258:     ui.instruction.textContent = 'En el 1, agarrá el concepto. En el 3, buscá el remate.';
259:     ui.hit.disabled = true;
260:     showEmptyRhymes();
261:   }
