283:   function setMode(mode) {
284:     if (!PROMPTS[mode]) return;
285:     state.mode = mode;
286:     document.body.classList.toggle('mode-double', mode === 'doble');
287:     ui.modeButtons.forEach((button) => {
288:       const active = button.dataset.mode === mode;
289:       button.classList.toggle('active', active);
290:       button.setAttribute('aria-pressed', String(active));
291:     });
292:     if (state.bpm) ui.tempoCaption.textContent = `Pulso estimado · ${effectiveTempo()} BPM de práctica`;
293:     restartClockPhase();
294:   }
295: 
296:   function restartClockPhase() {
297:     if (!state.running) return;
298:     state.generation += 1;
299:     window.clearTimeout(state.timer);
300:     state.tickTimerIds.forEach((id) => window.clearTimeout(id));
301:     state.tickTimerIds.clear();
302:     state.tickNumber = 0;
303:     state.nextTickAt = performance.now() + 70;
304:     scheduleLoop(state.generation);
305:   }
306: 
307:   function stopClock() {
308:     state.running = false;
309:     state.generation += 1;
310:     window.clearTimeout(state.timer);
311:     state.tickTimerIds.forEach((id) => window.clearTimeout(id));
312:     state.tickTimerIds.clear();
313:     ui.beatBoxes.forEach((box) => box.classList.remove('active', 'sub-beat'));
314:     setTempoReady(Boolean(state.bpm));
315:   }
316: 
317:   function resetSession() {
318:     stopClock();
319:     state.tapTimes = [];
320:     state.intervals = [];
321:     state.bpm = null;
322:     state.roundNumber = 0;
323:     state.currentPrompt = null;
324:     state.rhymeRevealed = false;
325:     state.hitThisRound = false;
326:     state.streak = 0;
327:     state.hits = 0;
328:     ui.bpm.textContent = '—';
329:     ui.tempoCaption.textContent = 'Tocá al ritmo de tu base';
330:     ui.hit.innerHTML = '¡LA EMBOQUÉ! <span>↗</span>';
331:     renderEmptyPrompt();
332:     updateStats();
333:     saveProgress();
334:     showToast('Sesión reiniciada. El récord queda guardado.');
335:   }
336: 
337:   function pulseTapButton() {
338:     ui.tap.classList.add('pulse');
339:     window.setTimeout(() => ui.tap.classList.remove('pulse'), 110);
340:   }
341: 
342:   function toggleSound() {
343:     state.soundOn = !state.soundOn;
344:     if (state.soundOn) resumeAudio();
345:     updateSoundButton();
346:     showToast(state.soundOn ? 'Metrónomo sonoro activado.' : 'Metrónomo sonoro silenciado.');
347:   }
348: 
349:   function updateSoundButton() {
350:     ui.sound.classList.toggle('active', state.soundOn);
351:     ui.sound.setAttribute('aria-pressed', String(state.soundOn));
352:     ui.sound.setAttribute('aria-label', state.soundOn ? 'Silenciar metrónomo' : 'Activar metrónomo sonoro');
353:     ui.sound.title = state.soundOn ? 'Silenciar metrónomo' : 'Activar metrónomo sonoro';
354:   }
355: 
356:   function resumeAudio() {
357:     const AudioContextClass = window.AudioContext || window.webkitAudioContext;
358:     if (!AudioContextClass) return;
359:     try {
360:       if (!state.audio) state.audio = new AudioContextClass();
361:       if (state.audio.state === 'suspended') state.audio.resume();
362:     } catch (_) {
363:       // Visual timing remains available if Web Audio is unavailable.
364:     }
365:   }
366: 
367:   function scheduleClick(time, accented) {
368:     if (!state.audio || state.audio.state !== 'running') return;
369:     try {
370:       const oscillator = state.audio.createOscillator();
371:       const gain = state.audio.createGain();
372:       const start = state.audio.currentTime + Math.max(0, time - performance.now()) / 1000;
373:       oscillator.type = 'sine';
374:       oscillator.frequency.value = accented ? 880 : 590;
375:       gain.gain.setValueAtTime(0.0001, start);
376:       gain.gain.exponentialRampToValueAtTime(accented ? 0.11 : 0.055, start + 0.004);
377:       gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.045);
378:       oscillator.connect(gain);
379:       gain.connect(state.audio.destination);
380:       oscillator.start(start);
381:       oscillator.stop(start + 0.05);
382:       oscillator.onended = () => { oscillator.disconnect(); gain.disconnect(); };
383:     } catch (_) {
384:       // A missed sound must not stop the visual beat scheduler.
385:     }
386:   }
387: 
388:   function showToast(message) {
389:     ui.toast.textContent = message;
390:     ui.toast.classList.add('show');
391:     window.clearTimeout(state.toastTimer);
392:     state.toastTimer = window.setTimeout(() => ui.toast.classList.remove('show'), 1900);
393:   }
394: 
395:   function handleYouTubeSubmit(event) {
396:     event.preventDefault();
397:     const media = parseYouTubeUrl(ui.url.value);
398:     if (!media) {
399:       ui.playerStatus.textContent = 'Ese link no parece un video o playlist compatible de YouTube.';
400:       ui.url.focus();
401:       return;
402:     }
403:     state.pendingMedia = media;
404:     ui.playerFrame.hidden = false;
405:     ui.playerStatus.textContent = media.type === 'playlist' ? 'Preparando playlist de YouTube…' : 'Preparando video de YouTube…';
406:     if (state.player) {
407:       try { state.player.destroy(); } catch (_) { /* Ignore stale player cleanup errors. */ }
408:       state.player = null;
409:     }
410:     ui.player.replaceChildren();
411:     loadYouTubeApi();
412:   }
413: 
414:   function parseYouTubeUrl(value) {
415:     const raw = String(value || '').trim();
416:     if (!raw || raw.length > 2048) return null;
417:     let url;
418:     try {
419:       url = new URL(/^[a-z][a-z\d+.-]*:/i.test(raw) ? raw : `https://${raw}`);
420:     } catch (_) {
421:       return null;
422:     }
423:     if (!['https:', 'http:'].includes(url.protocol) || url.username || url.password) return null;
424:     const host = url.hostname.toLowerCase().replace(/\.$/, '');
425:     const isYoutube = host === 'youtube.com' || host.endsWith('.youtube.com');
426:     const isShort = host === 'youtu.be';
427:     if (!isYoutube && !isShort) return null;
428:     const playlistId = url.searchParams.get('list');
429:     const validPlaylist = playlistId && /^[A-Za-z0-9_-]{10,120}$/.test(playlistId);
430:     let videoId = '';
431:     if (isShort) videoId = url.pathname.split('/').filter(Boolean)[0] || '';
432:     else if (url.pathname === '/watch') videoId = url.searchParams.get('v') || '';
433:     else {
434:       const match = url.pathname.match(/^\/(?:embed|shorts|live)\/([A-Za-z0-9_-]{11})(?:\/|$)/);
435:       if (match) videoId = match[1];
436:     }
437:     if (/^[A-Za-z0-9_-]{11}$/.test(videoId)) return { type: 'video', id: videoId };
438:     if (validPlaylist) return { type: 'playlist', id: playlistId };
439:     return null;
440:   }
441: 
442:   function loadYouTubeApi() {
443:     if (window.YT && window.YT.Player) {
444:       createYouTubePlayer();
445:       return;
446:     }
447:     if (state.apiState === 'loading') return;
448:     state.apiState = 'loading';
449:     const previousCallback = window.onYouTubeIframeAPIReady;
450:     window.onYouTubeIframeAPIReady = () => {
451:       if (typeof previousCallback === 'function') {
452:         try { previousCallback(); } catch (_) { /* Do not block this player. */ }
453:       }
454:       state.apiState = 'ready';
455:       createYouTubePlayer();
456:     };
457:     let script = document.querySelector('script[data-rapea-youtube-api]');
458:     if (!script) {
459:       script = document.createElement('script');
460:       script.src = 'https://www.youtube.com/iframe_api';
461:       script.async = true;
462:       script.dataset.rapeaYoutubeApi = 'true';
463:       script.onerror = () => {
464:         state.apiState = 'idle';
465:         ui.playerStatus.textContent = 'No se pudo conectar con YouTube. Podés seguir practicando sin el reproductor.';
466:       };
467:       document.head.append(script);
468:     }
469:     window.setTimeout(() => {
470:       if (state.apiState === 'loading') {
471:         state.apiState = 'idle';
472:         ui.playerStatus.textContent = 'YouTube tarda en responder o está bloqueado. Volvé a cargar el link para reintentar.';
473:       }
474:     }, 12000);
475:   }
476: 
477:   function createYouTubePlayer() {
478:     if (!state.pendingMedia || !window.YT || !window.YT.Player) return;
479:     state.apiState = 'ready';
480:     const media = state.pendingMedia;
481:     try {
482:       state.player = new window.YT.Player(ui.player, {
483:         width: '100%', height: '100%',
484:         playerVars: { autoplay: 0, controls: 1, playsinline: 1, rel: 0 },
